class Literal:
  # See https://docs.jax.dev/en/latest/internals/constants.html
  __slots__ = ["val", "aval"]

  val: Any
  aval: AbstractValue

  def __init__(self, val, aval):

  # This is equivalent to "with take_current_trace()", but the bind() code
  # is called frequently and it's slightly faster to avoid using a context
  # manager object.
  prev_trace = trace_ctx.trace
  trace_ctx.set_trace(None)
  try:
    return self.bind_with_trace(prev_trace, args, avals, params)
  finally:
    trace_ctx.set_trace(prev_trace)

def bind_with_trace(self, trace, args, avals, params, /):
  if self.is_high(*avals, **params) and trace.requires_low:
    with set_current_trace(trace):
      return self.to_lojax(*args, **params)
  return trace.process_primitive(self, args, params)

class EvalTrace(Trace):

  def stage_value(self, val):
    if isinstance(val, Array):
      return val
    return self.process_primitive(stage_p, [val], {})

  def process_primitive(self, primitive, args, params, /):
    with set_current_trace(self):
      if config.debug_key_reuse.value:
        from jax.experimental.key_reuse._core import call_impl_with_key_reuse_checks  # pyrefly: ignore[missing-import]
        return call_impl_with_key_reuse_checks(primitive, primitive.impl, *args, **params)
      else:
        # TODO(dougalm): delete. this shouldn't be necessary
        args = map(full_lower, args)
        check_eval_args(args)
        return primitive.impl(*args, **params)

class TracingContext:
  __slots__ = ()

  @staticmethod
  def reset():
    trace_state.set_local(config_ext.unset)
    trace_state_strong_ref.set_local(config_ext.unset)
    axis_env_state.set_local(config_ext.unset)

  @property
  def trace(self):
    return trace_state_strong_ref.value

  @property
  def axis_env(self):
    return axis_env_state.value

  def is_top_level(self) -> bool:
    return self.trace is eval_trace and self.axis_env is top_axis_env

  def is_empty(self) -> bool:
    return self.trace is None

def process_primitive(self, primitive, tracers, params, /):
  self.frame.is_high |= primitive.is_high(*map(typeof, tracers), **params)
  if config.eager_constant_folding.value and not any(isinstance(x, Tracer) for x in tracers):
    avals = tuple(core.typeof(x) for x in tracers)
    return primitive.bind_with_trace(core.eval_trace, tracers, avals, params)
  source_info = source_info_util.current()
  to_jaxpr_tracer = partial(self.to_jaxpr_tracer, source_info=source_info)
  jaxpr_tracers = map(to_jaxpr_tracer, tracers)
  if primitive in custom_staging_rules:
    return custom_staging_rules[primitive](self, source_info, *jaxpr_tracers,
                                           **params)
  return self.default_process_primitive(
      primitive, jaxpr_tracers, params, source_info)

class JVPTrace(Trace):
  def __init__(self, parent_trace, tag):
    super().__init__()
    self.tag = tag
    self.parent_trace = parent_trace
    self.requires_low = False

  def to_primal_tangent_pair(self, val):
    if isinstance(val, JVPTracer) and val._trace.tag is self.tag:
      return (val.primal, val.tangent)
    else:
      tangent_zero = p2tz(val)
      return (val, tangent_zero)

  def stage_value(self, val):
    primal, tangent = self.to_primal_tangent_pair(val)
    new_primal = self.parent_trace.stage_value(primal)
    if type(tangent) is Zero:
      return new_primal
    else:
      new_tangent = self.parent_trace.stage_value(tangent)
      return JVPTracer(self, new_primal, new_tangent)

  def process_primitive(self, primitive, tracers, params, /):
    primals_in, tangents_in = unzip2(map(self.to_primal_tangent_pair, tracers))
    if (all(type(t) is Zero for t in tangents_in) and
        primitive is not core.ref_p and primitive is not core.empty_ref_p and
        not any(isinstance(typeof(x), AbstractRef) for x in primals_in)):
      avals = tuple(core.typeof(x) for x in primals_in)
      return primitive.bind_with_trace(self.parent_trace, primals_in, avals, params)
    jvp = primitive_jvps.get(primitive)
    if not jvp:
      msg = f"Differentiation rule for '{primitive}' not implemented"
      raise NotImplementedError(msg)
    with core.set_current_trace(self.parent_trace):
      primal_out, tangent_out = jvp(primals_in, tangents_in, **params)

    if primitive.multiple_results:
      return [maybe_jvp_tracer(self, x, t) for x, t in zip(primal_out, tangent_out)]
    else:
      return maybe_jvp_tracer(self, primal_out, tangent_out)

def process_primitive(self, p, tracers, params, /):
  vals_in, dims_in = unzip2(map(self.to_batch_info, tracers))
  unmapped_args = all(bdim is None for bdim in dims_in)
  if p in fancy_primitive_batchers:
    # TODO(yashkatariya): Remove remove_explicit_mesh_axis_names when vmap
    # mesh ctx is correctly set.
    with (core.set_current_trace(self.parent_trace),
          core.remove_explicit_mesh_axis_names(self.axis_data.explicit_mesh_axis)):
      val_out, dim_out = fancy_primitive_batchers[p](
          self.axis_data, vals_in, dims_in, **params)
      src = source_info_util.current()
      if p.multiple_results:
        return [BatchTracer(self, x, d, src) if d is not None else x
                for x, d in zip(val_out, dim_out)]
      else:
        return (BatchTracer(self, val_out, dim_out, src)
                if dim_out is not None else val_out)
  elif unmapped_args:  # Not all primitives have batching rules defined
    avals = tuple(core.typeof(x) for x in vals_in)
    return p.bind_with_trace(self.parent_trace, tuple(vals_in), avals,
                             dict(params))
  else:
    raise NotImplementedError(f"Batching rule for '{p}' not implemented")

